isLeapYear.tests:
test('ordinary leap years', () => {
  eq(isLeapYear(2024), true);
  eq(isLeapYear(1996), true);
});

test('ordinary common years', () => {
  eq(isLeapYear(2023), false);
  eq(isLeapYear(2019), false);
});

test('centuries are not leap years', () => {
  eq(isLeapYear(1900), false);
  eq(isLeapYear(2100), false);
});

test('every 400th year is', () => {
  eq(isLeapYear(2000), true);
  eq(isLeapYear(1600), true);
});
